import{_ as d,C as i,o as c,c as n,j as s,a,E as t,a2 as r}from"./chunks/framework.BxGh02fV.js";const v=JSON.parse('{"title":"Run the work","description":"","frontmatter":{"title":"Run the work"},"headers":[],"relativePath":"en/agent/piloter.md","filePath":"en/agent/piloter.md"}'),l={name:"en/agent/piloter.md"};function h(f,o,p,y,u,g){const e=i("Ask");return c(),n("div",null,[o[0]||(o[0]=s("h1",{id:"run-the-work",tabindex:"-1"},[a("Run the work "),s("a",{class:"header-anchor",href:"#run-the-work","aria-label":'Permalink to "Run the work"'},"​")],-1)),o[1]||(o[1]=s("p",null,"Epics, their stories and their tasks make up the work tree. You come here to ask the agent to create it, move it forward, pause it or close it, without touching the files yourself.",-1)),o[2]||(o[2]=s("h2",{id:"what-you-ask-the-agent",tabindex:"-1"},[a("What you ask the agent "),s("a",{class:"header-anchor",href:"#what-you-ask-the-agent","aria-label":'Permalink to "What you ask the agent"'},"​")],-1)),t(e,{say:'Open an epic "Data export" in the Data zone.',verb:"effortless_epic_start",family:"cycle-de-vie",args:'{"zone":"Data","title":"Data export"}'}),t(e,{say:'Create a story "CSV export" in this epic and activate it.',verb:"effortless_story_start",family:"cycle-de-vie",args:'{"title":"CSV export","activate":true}'}),t(e,{say:"Add three tasks to the story: the format, the button, the tests.",verb:"effortless_task_add",family:"cycle-de-vie",args:'{"title":"The format"}'}),t(e,{say:"Set task TSK-02 of story 003 of epic 012 to in progress.",verb:"effortless_task_update",family:"cycle-de-vie",args:'{"epic_id":"012","story_id":"003","task_id":"TSK-02","status":"Doing"}'}),t(e,{say:"That is enough for today: pause the story, reason: we are waiting for the customer's answer.",verb:"effortless_story_pause",family:"cycle-de-vie",args:'{"reason":"We are waiting for the customer’s answer"}'}),t(e,{say:"Pick up story 003 again, yesterday's.",verb:"effortless_story_activate",family:"cycle-de-vie",args:'{"story_id":"003"}'}),t(e,{say:"This story is done: close it, then close the epic.",verb:"effortless_story_complete",family:"cycle-de-vie"}),t(e,{say:"Story 004 was replaced by 006: mark it as such.",verb:"effortless_story_supersede",family:"cycle-de-vie",args:'{"story_id":"004","by":"006"}'}),t(e,{say:"Retire story 007: the feature is dropped.",verb:"effortless_story_retire",family:"cycle-de-vie",args:'{"story_id":"007","reason":"feature dropped"}'}),o[3]||(o[3]=r('<h2 id="what-the-agent-does" tabindex="-1">What the agent does <a class="header-anchor" href="#what-the-agent-does" aria-label="Permalink to &quot;What the agent does&quot;">​</a></h2><h3 id="create-and-activate-an-epic" tabindex="-1">Create and activate an epic <a class="header-anchor" href="#create-and-activate-an-epic" aria-label="Permalink to &quot;Create and activate an epic&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/cycle-de-vie.html#epic-start"><code>effortless_epic_start</code></a>: creates the epic in a <code>zone</code>, with a <code>title</code> and an optional <code>description</code>. By default (<code>activate</code> set to <code>true</code>) it becomes the active epic; <code>activate: false</code> just creates it.</li><li><a href="/Effortless/en/reference/mcp/cycle-de-vie.html#epic-activate"><code>effortless_epic_activate</code></a>: reactivates an <strong>existing</strong> epic (<code>epic_id</code>) without going through a story. It clears the active story. Replayed, it changes nothing.</li></ol><h3 id="create-and-activate-a-story" tabindex="-1">Create and activate a story <a class="header-anchor" href="#create-and-activate-a-story" aria-label="Permalink to &quot;Create and activate a story&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/cycle-de-vie.html#story-start"><code>effortless_story_start</code></a>: creates the story in the active epic or in <code>epic_id</code>. Useful parameters: <code>title</code>, <code>slug</code>, <code>zone</code>, <code>depends_on</code>, <code>objective</code>, <code>activate</code>. <code>kind</code> is <code>opale</code> (default, with framing) or <code>fix</code> (direct fix, see <a href="/Effortless/en/agent/cadrer.html">Frame work with OPALE</a>). <code>taskless_reason</code> says why a story will have no task (pure framing, milestone, decision).</li><li><a href="/Effortless/en/reference/mcp/cycle-de-vie.html#story-activate"><code>effortless_story_activate</code></a>: activates an existing story (<code>story_id</code>) and reopens its epic if needed.</li><li><a href="/Effortless/en/reference/mcp/cycle-de-vie.html#story-objective"><code>effortless_story_objective</code></a>: sets or corrects the story&#39;s objective, in one or two sentences. An empty string removes it.</li></ol><h3 id="add-tasks" tabindex="-1">Add tasks <a class="header-anchor" href="#add-tasks" aria-label="Permalink to &quot;Add tasks&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/cycle-de-vie.html#task-add"><code>effortless_task_add</code></a>: adds a <strong>Todo</strong> task to the active story (or to <code>story_id</code>). The agent can pass <code>description</code>, <code>phase</code>, <code>stack</code> (the development standards that apply to it; a standard that does not exist is refused) and an optional routing classification (<code>complexity</code>, <code>capability_tier</code>, <code>effort_level</code>). The engine returns the <code>TSK-NN</code> identifier.</li><li><a href="/Effortless/en/reference/mcp/cycle-de-vie.html#story-items"><code>effortless_story_items</code></a>: reads back a story&#39;s decisions, questions and tasks.</li></ol><h3 id="move-a-task-forward" tabindex="-1">Move a task forward <a class="header-anchor" href="#move-a-task-forward" aria-label="Permalink to &quot;Move a task forward&quot;">​</a></h3><p><a href="/Effortless/en/reference/mcp/cycle-de-vie.html#task-update"><code>effortless_task_update</code></a> changes a task&#39;s status (<code>Todo</code>, <code>Doing</code>, <code>Done</code>, shown as <strong>To do</strong>, <strong>In progress</strong>, <strong>Done</strong> in the app), its title, its description and its result. It requires at least one field.</p><ul><li>Moving to <strong>In progress</strong> is refused while the story&#39;s framing is not complete, or while a task this one depends on is not done.</li><li>When finishing a task, the agent fills in <code>result</code>: what it produced, as observed (files, verbs, measurements). This text appears on the task&#39;s page in the Backlog.</li></ul><h3 id="pause-resume-reloop" tabindex="-1">Pause, resume, reloop <a class="header-anchor" href="#pause-resume-reloop" aria-label="Permalink to &quot;Pause, resume, reloop&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/cycle-de-vie.html#story-pause"><code>effortless_story_pause</code></a>: pauses the story (the active one by default), dates the pause and releases the active story. <code>reason</code> is mandatory. No task is touched.</li><li><a href="/Effortless/en/reference/mcp/cycle-de-vie.html#story-activate"><code>effortless_story_activate</code></a> resumes it, and you find everything as it was left.</li><li><a href="/Effortless/en/reference/mcp/cycle-de-vie.html#story-reloop"><code>effortless_story_reloop</code></a>: sends the active story back to an earlier OPALE phase (<code>target_phase</code>).</li></ol><h3 id="close-supersede-retire-archive" tabindex="-1">Close, supersede, retire, archive <a class="header-anchor" href="#close-supersede-retire-archive" aria-label="Permalink to &quot;Close, supersede, retire, archive&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/cycle-de-vie.html#story-complete"><code>effortless_story_complete</code></a>: closes the story. It must have at least one task, and all of them must be done.</li><li><a href="/Effortless/en/reference/mcp/cycle-de-vie.html#story-supersede"><code>effortless_story_supersede</code></a>: declares that the story (<code>story_id</code>) is replaced by another one in the same epic (<code>by</code>). It no longer blocks closing the epic and is not counted as delivered.</li><li><a href="/Effortless/en/reference/mcp/cycle-de-vie.html#story-retire"><code>effortless_story_retire</code></a>: retires a <strong>not started</strong> story that will not be done, with its reason (<code>reason</code>, required). It no longer blocks closing the epic, can be archived, and is never counted as delivered; the register shows &quot;retirée :&quot; followed by the reason. The verb refuses a story with a task already done: close it, or declare it superseded.</li><li><a href="/Effortless/en/reference/mcp/cycle-de-vie.html#story-archive"><code>effortless_story_archive</code></a>: archives a story that is already done, superseded or retired. The <code>.effortless/crew_contracts/&lt;epic&gt;/&lt;story&gt;/</code> folder of its contracts is destroyed. Replayed, it changes nothing.</li><li><a href="/Effortless/en/reference/mcp/cycle-de-vie.html#epic-complete"><code>effortless_epic_complete</code></a>: closes the epic (the active one by default). Every story must be done, superseded or retired. Closing resolves no evolution of the register: those still <strong>In progress</strong> are named in the reply (<code>evolutions_maintained</code>), and the agent asks you what to do with them (see <a href="/Effortless/en/agent/evolutions.html">Evolutions register</a>).</li></ol><h2 id="objectives-milestones-and-deliverables" tabindex="-1">Objectives, milestones and deliverables <a class="header-anchor" href="#objectives-milestones-and-deliverables" aria-label="Permalink to &quot;Objectives, milestones and deliverables&quot;">​</a></h2><p>In a non-code project (<code>gestion-de-projet</code> model), the agent also keeps the steering register: the objectives, their milestones, the deliverables expected at each milestone and the resources doing the work. States (rate, <code>a-venir</code>, <code>en-cours</code>, <code>atteint</code>) are computed, never typed in.</p>',16)),t(e,{say:'Add a deliverable "Write the user guide", of type document, in docs/user-guide.md.',verb:"effortless_pilotage_upsert",family:"objectifs",args:'{"kind":"deliverable","item":{"title":"Write the user guide","kind":"document","path":"docs/user-guide.md"}}'}),t(e,{say:"Is the user guide LIV-01 complete? Run the completeness analysis.",verb:"effortless_deliverable_check",family:"objectifs",args:'{"id":"LIV-01"}'}),t(e,{say:"I have reviewed the user guide LIV-01: I accept it.",verb:"effortless_deliverable_review",family:"objectifs",args:'{"id":"LIV-01","verdict":"accepted"}'}),o[4]||(o[4]=r('<ol><li><a href="/Effortless/en/reference/mcp/objectifs.html#pilotage-show"><code>effortless_pilotage_show</code></a>: reads the register and its computed state. Without a register, it returns empty lists and writes nothing.</li><li><a href="/Effortless/en/reference/mcp/objectifs.html#pilotage-upsert"><code>effortless_pilotage_upsert</code></a> and <a href="/Effortless/en/reference/mcp/objectifs.html#pilotage-remove"><code>effortless_pilotage_remove</code></a>: add, replace or remove an objective, a milestone, a deliverable or a resource. An object that is still cited cannot be removed.</li><li><a href="/Effortless/en/reference/mcp/objectifs.html#task-effort"><code>effortless_task_effort</code></a>: sets a task&#39;s estimate, adds time spent and assigns it to a resource.</li><li><a href="/Effortless/en/reference/mcp/objectifs.html#deliverable-check"><code>effortless_deliverable_check</code></a> then <a href="/Effortless/en/reference/mcp/objectifs.html#deliverable-report"><code>effortless_deliverable_report</code></a>: the agent receives the analysis contract, measures what is present against what is planned, without judging quality, and returns one result per criterion.</li><li><a href="/Effortless/en/reference/mcp/objectifs.html#deliverable-review"><code>effortless_deliverable_review</code></a>: your review. It is the only gesture that makes a deliverable validated; the agent calls it only when you ask. You can also decide on screen (<a href="/Effortless/en/guide/objectifs.html">Objectives and milestones</a>): that gesture is recorded <code>by: &quot;ecran&quot;</code> and is not subject to <code>semi-auto</code> mode, since you are the one deciding.</li></ol><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><ul><li>The work tree in the <a href="/Effortless/en/guide/backlog.html">Backlog</a> screen: epics, stories, tasks, with their phase and status. A story&#39;s page shows its objective; a task&#39;s page shows what it produced.</li><li>The task in progress and the story&#39;s task counter on the <a href="/Effortless/en/guide/dashboard.html">Dashboard</a> and in the <a href="/Effortless/en/guide/tasks.html">Tasks</a> screen.</li><li>The same information rendered as Markdown in <code>blueprints/</code> (for example <code>blueprints/3-Backlog.md</code>).</li></ul><h2 id="when-the-agent-is-refused" tabindex="-1">When the agent is refused <a class="header-anchor" href="#when-the-agent-is-refused" aria-label="Permalink to &quot;When the agent is refused&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>What the refusal says</th><th>What to do</th></tr></thead><tbody><tr><td>No active story and no <code>story_id</code> passed</td><td><code>pilotage:noActiveStory</code></td><td>Pass <code>epic_id</code> and <code>story_id</code>, or activate a story.</td></tr><tr><td>Activating an epic without naming it</td><td><code>pilotage:epicActivateNeedsId</code></td><td>Name the epic; <code>epic_start</code> creates a new one.</td></tr><tr><td>Activating an unknown epic</td><td><code>pilotage:epicUnknownCannotActivate</code></td><td>Use <code>epic_start</code> to create one, or <code>status</code> to see the existing ones.</td></tr><tr><td>Activating an epic that is already closed</td><td><code>pilotage:epicDoneCannotActivate</code></td><td>Activate one of its stories: that reopens the epic.</td></tr><tr><td>Closing a story with no task</td><td><code>pilotage:storyNoTask</code></td><td>Declare the work with <code>task_add</code> before closing.</td></tr><tr><td>Closing a story with tasks not done</td><td><code>pilotage:storyTasksNotDone</code></td><td>Finish the tasks.</td></tr><tr><td>Closing an epic with stories not done</td><td><code>pilotage:epicStoriesNotDone</code></td><td>Close each story named by the refusal, or declare it superseded.</td></tr><tr><td>Pausing a story without a reason</td><td><code>pilotage:storyPauseNeedsReason</code></td><td>Pass <code>reason</code>.</td></tr><tr><td>Pausing a story that is already done</td><td><code>pilotage:storyDoneCannotPause</code></td><td>Reopen it with <code>story_activate</code> if the work resumes.</td></tr><tr><td>Unknown story</td><td><code>pilotage:storyUnknown</code></td><td>Read the existing stories again (<code>story_items</code>, <code>project_tree</code>).</td></tr><tr><td>Superseding a story by itself or by a story of another epic</td><td><code>pilotage:supersederInvalid</code></td><td>Pass in <code>by</code> another story of the same epic.</td></tr><tr><td>Superseding a story that is already closed</td><td><code>pilotage:storyAlreadyClosed</code></td><td>Nothing: a closed story stays closed.</td></tr><tr><td>Archiving a story that is not done</td><td><code>pilotage:storyNotDoneCannotArchive</code></td><td>Close it first.</td></tr><tr><td>Updating a task with no field</td><td><code>pilotage:taskUpdateEmpty</code></td><td>Pass at least <code>status</code>, <code>title</code>, <code>description</code> or <code>result</code>.</td></tr><tr><td>Task to <strong>In progress</strong> while the framing is unfinished</td><td><code>cadrage:phaseIncomplete</code></td><td>Provide the missing documents, or open a direct fix (<code>kind: &quot;fix&quot;</code>).</td></tr><tr><td>Task to <strong>In progress</strong> while a task it depends on is not done</td><td>refusal without a code, naming the dependency</td><td>Finish the dependency task first.</td></tr><tr><td>Development standard in <code>stack</code> that does not exist</td><td><code>pilotage:nddUnknown</code></td><td>Pass the name of a standard present in <code>.ai/ndd/</code>.</td></tr><tr><td>Reviewing a deliverable the team loop is waiting on (<code>review</code> stage)</td><td><code>pilotage:reviewOwnedByLoop</code></td><td>Decide with <code>effortless_crew_review</code>, or from the panel of the Objectives and milestones screen.</td></tr></tbody></table>',5))])}const _=d(l,[["render",h]]);export{v as __pageData,_ as default};
